function RetentionAdmin() {
  const { site } = useSite();
  const qc = useQueryClient();
  const query = useQuery({
    queryKey: ["retention", site?.site_id],
    queryFn: ({ signal }) =>
      get<{
        policy: RetentionPolicy;
        updated_at?: string;
        last_run?: RetentionRun | null;
      }>(`/api/v1/sites/${site!.site_id}/retention`, { signal }),
    enabled: !!site,
  });
  const [local, setLocal] = useState<RetentionPolicy | null>(null);
  useUnsavedWarning(local !== null);
  const current = local || query.data?.policy;
  const save = useMutation({
    meta: { successMessage: "저장했습니다." },
    mutationFn: () => put(`/api/v1/sites/${site!.site_id}/retention`, current),
    onSuccess: async () => {
      setLocal(null);
      await qc.invalidateQueries({ queryKey: ["retention", site?.site_id] });
    },
  });
  if (!site) return <NoSite />;
  if (query.isLoading) return <Loading />;
  if (query.error)
    return <ErrorState error={query.error} retry={() => query.refetch()} />;
  const set = (key: keyof RetentionPolicy, value: number | null) =>
    setLocal({ ...query.data!.policy, ...local, [key]: value });
  return (
    <Stack spacing={2}>
      <Alert severity="info">
        정책은 사이트별로 적용됩니다. Raw Event와 물리화 Session은 매시간
        독립적으로 정리되며 집계 보존기간을 비워 두면 무기한입니다.
      </Alert>
      <RetentionRunCard run={query.data?.last_run} />
      <Card sx={{ p: 3 }}>
        <Section
          title={`${site.name} 보존 정책`}
          desc="법무·보안 정책에 맞춰 데이터 종류별 보존기간을 지정합니다."
        >
          <Box
            sx={{
              display: "grid",
              gridTemplateColumns: {
                xs: "1fr",
                md: "repeat(2,1fr)",
                xl: "repeat(3,1fr)",
              },
              gap: 2,
            }}
          >
            {/*
              라벨·helperText·오류 색은 retentionRule.ts 가 정한다 — 범위를
              말하는 문장이 저장 실패 Alert(describeRetentionError)과 같은
              상수에서 나오게 해서, 둘이 갈라질 수 없게 한다. 그 전에는 이 두
              칸이 범위를 아예 말하지 않아 저장을 눌러 400 을 받은 뒤에야 1~120
              을 읽었다.
            */}
            <TextField
              type="number"
              value={current?.raw_event_months ?? 13}
              onChange={(event) =>
                set("raw_event_months", Number(event.target.value))
              }
              {...retentionFieldProps(
                "raw_event_months",
                current?.raw_event_months ?? 13,
              )}
            />
            <TextField
              type="number"
              value={current?.session_months ?? 25}
              onChange={(event) =>
                set("session_months", Number(event.target.value))
              }
              {...retentionFieldProps(
                "session_months",
                current?.session_months ?? 25,
              )}
            />
            <TextField
              type="number"
              value={current?.aggregation_months ?? ""}
              onChange={(event) =>
                set(
                  "aggregation_months",
                  event.target.value ? Number(event.target.value) : null,
                )
              }
              {...retentionFieldProps(
                "aggregation_months",
                current?.aggregation_months ?? null,
              )}
            />
            <TextField
              type="number"
              value={current?.realtime_hours ?? 24}
              onChange={(event) =>
                set("realtime_hours", Number(event.target.value))
              }
              {...retentionFieldProps(
                "realtime_hours",
                current?.realtime_hours ?? 24,
              )}
            />
            <TextField
              type="number"
              value={current?.debug_days ?? 7}
              onChange={(event) =>
                set("debug_days", Number(event.target.value))
              }
              {...retentionFieldProps("debug_days", current?.debug_days ?? 7)}
            />
          </Box>
          {save.error && <RetentionErrorAlert error={save.error} />}
          <Button
            variant="contained"
            startIcon={<SaveRounded />}
            disabled={!local || save.isPending}
            onClick={() => save.mutate()}
          >
            보존 정책 저장
          </Button>
        </Section>
      </Card>
    </Stack>
  );
}

